package loops;

public class PyramidNumber {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		for (int r=5;r>=1;r++)// r=3
		{
			for (int c=r-1;c<=5;c++)//c=2 2<=3 t
								
			{
				System.out.print(r);//1
									//12
									
			}
			System.out.println();

	}

}
}